// Upgrade an existing V9 database through the production IndexedDB migration.
import {openIDB} from '../static/engine.mjs';
const name='topic-transfer-upgrade-'+crypto.randomUUID(),conv='a'.repeat(64),id='b'.repeat(32),fp='11111111-11111111-11111111-11111111';
const original={v:2,id,lid:id,conv,from:'bob/desk',fp,kind:'message',body:'Existing source bytes stay unchanged',at:1000,contribution_review:{body:'Legacy retained preview plaintext'}};
const control={v:2,id:'c'.repeat(32),lid:'c'.repeat(32),conv,from:'bob/desk',fp,kind:'message',control:true,sub:'revision',ref:{id,fingerprint:fp},body:'{"rev":1,"text":"Current text"}',at:2000};
const old=await new Promise((resolve,reject)=>{const r=indexedDB.open(name,9);r.onupgradeneeded=()=>{for(const s of ['kv','pins','persons','convs','inbox','outbox','held','lids','receipts','files','erased'])r.result.createObjectStore(s);for(const name of ['inbox','outbox']){const store=r.transaction.objectStore(name);for(const key of ['conv','thread_peer','device_arrival','history_pos','state'])store.createIndex(key,key);if(name==='inbox'){store.createIndex('history_arrival','history_arrival');store.createIndex('status','status');}else{store.createIndex('sub','sub');store.createIndex('recipient_state',['to','state']);store.createIndex('lane_demote','lane_demote');}}};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});
await new Promise((resolve,reject)=>{const tx=old.transaction('inbox','readwrite');tx.objectStore('inbox').put(original,id);tx.objectStore('inbox').put(control,control.id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});old.close();
const store=await openIDB(name),rows=await store.transferOriginal('inbox',conv,id),meta=await store.transferMeta('inbox',conv);
if(rows.length!==1||rows[0].body!==original.body||meta.length!==1||meta[0].body!==control.body)throw Error('V9 originals and metadata did not become exact indexed selectors.');
const after=await store.get('inbox',id);if(after.contribution_review)throw Error('Upgrade retained obsolete preview plaintext.');for(const[k,v]of Object.entries(original))if(k!=='contribution_review'&&(JSON.stringify(after[k])!==JSON.stringify(v)))throw Error('Upgrade changed original field '+k);
store.close();await new Promise(resolve=>{const r=indexedDB.deleteDatabase(name);r.onsuccess=r.onerror=r.onblocked=resolve;});window.topicTransferUpgradeResult={ok:true,checks:4,storage:'IndexedDB'};
